function v4ApplyStoredJSON(json){
  try{
    const raw=safeJSONParse(json);if(!raw)throw new Error("GeÃ§ersiz JSON kaydÄ±");
    if(Number(raw.v||1)>DATA_SCHEMA)throw new Error("KayÄ±t daha yeni veri ÅŸemasÄ±na ait");
    const next=normalize(Object.assign({},JSON.parse(JSON.stringify(DEF)),migrateState(raw)));
    const persisted=JSON.stringify(next);if(!persisted||persisted.length>MAX_REASONABLE_STATE_BYTES)throw new Error("Veri boyutu gÃ¼venli sÄ±nÄ±rÄ± aÅŸtÄ±");
    localStorage.setItem(STORAGE_KEY,persisted);S=next;window.S=next;lastPersistedJSON=persisted;
    perfInvalidateState();persistStateHashMaybe(persisted,true);renderAfterExternalState();
    return {ok:true,json:persisted};
  }catch(error){
    infraError("v4-apply-indexed",error);return {ok:false,message:String(error&&error.message||error||"KayÄ±t uygulanamadÄ±")};
  }
}
try{window.YKSLegacyState={readJSON:()=>JSON.stringify(S),applyJSON:v4ApplyStoredJSON};}catch(e){}
