function publisherStats(type){
  const agg={};
  S.denemeler.filter(d=>d.type===type&&d.pub&&d.pub.trim()).forEach(d=>{
    const p=d.pub.trim();
    if(!agg[p])agg[p]={sum:0,n:0,min:Infinity,max:-Infinity};
    agg[p].sum+=d.totalNet; agg[p].n++;
    agg[p].min=Math.min(agg[p].min,d.totalNet);
    agg[p].max=Math.max(agg[p].max,d.totalNet);
  });
  return Object.keys(agg).map(p=>({pub:p,avg:r2(agg[p].sum/agg[p].n),n:agg[p].n,min:agg[p].min,max:agg[p].max}))
    .sort((a,b)=>b.avg-a.avg);
}
function renderPublishers(){
  const w=el("pubBox"); if(!w)return;
  const list=publisherStats(denemeType==="BRANS"?"TYT":denemeType);
  if(!list.length){ w.innerHTML='<div class="empty">Deneme kaydederken yayÄ±nevini de yazarsan, hangi yayÄ±nÄ±n seni daha Ã§ok zorladÄ±ÄŸÄ± burada gÃ¶rÃ¼nÃ¼r.</div>'; return; }
  let html='<table><tr><th style="text-align:left">YayÄ±n</th><th>Deneme</th><th>Ort. net</th><th>En dÃ¼ÅŸÃ¼kâ€“yÃ¼ksek</th></tr>';
  list.forEach(x=>{
    html+=`<tr><td style="text-align:left">${esc(x.pub)}</td><td>${x.n}</td>
      <td style="font-weight:700">${x.avg}</td><td>${x.min}â€“${x.max}</td></tr>`;
  });
  html+="</table>";
  if(list.length>1){
    const d=r2(list[0].avg-list[list.length-1].avg);
    html+=`<p class="hint"><b>${esc(list[0].pub)}</b> ile <b>${esc(list[list.length-1].pub)}</b> arasÄ±nda ${d} netlik fark var. Bu fark senin geliÅŸimin deÄŸil, denemelerin zorluk farkÄ± olabilir â€” ilerlemeyi Ã¶lÃ§erken aynÄ± yayÄ±nÄ±n denemelerini kendi iÃ§inde karÅŸÄ±laÅŸtÄ±r.</p>`;
  }
  w.innerHTML=html;
}

