/* ==================================================================
   2) KATSAYI KALÄ°BRASYONU â€” gerÃ§ek sonuÃ§la
   ================================================================== */
function addCalib(){
  const type=el("cbType").value;
  const net=parseFloat(el("cbNet").value);
  const score=parseFloat(el("cbScore").value);
  const ayt=parseFloat(el("cbAyt").value);
  if(!isFinite(net)||!isFinite(score)||net<0||score<=0){ toast("Net ve puanÄ± gir"); return; }
  if(type==="alan"&&!isFinite(ayt)){ toast("Alan puanÄ± iÃ§in AYT netini de gir"); return; }
  S.calib.push({id:Date.now(),type:type,net:r2(net),score:r2(score),
    ayt:type==="alan"?r2(ayt):null,date:todayKey()});
  save(); el("cbNet").value=""; el("cbScore").value=""; el("cbAyt").value="";
  renderCalib(); toast("SonuÃ§ eklendi âœ“");
}
function delCalib(id){
  const bk=clone(S.calib.find(x=>x.id===id));
  S.calib=S.calib.filter(x=>x.id!==id);
  if(bk&&typeof logAdd==="function")logAdd("sil","GerÃ§ek sonuÃ§ silindi",{t:"calib",v:bk});
  save();
  if(bk)pushUndo("SonuÃ§ silindi",()=>{ S.calib.push(bk); });
  renderCalib();
}
/* iki bilinmeyenli en kÃ¼Ã§Ã¼k kareler: score = base + k*net */
function fitLine(points){
  const n=points.length;
  if(!n)return null;
  if(n===1)return {k:null,base:null,single:points[0]};
  let sx=0,sy=0,sxx=0,sxy=0;
  points.forEach(p=>{ sx+=p.x; sy+=p.y; sxx+=p.x*p.x; sxy+=p.x*p.y; });
  const den=n*sxx-sx*sx;
  if(Math.abs(den)<1e-9)return {k:null,base:null,single:points[0]};
  const k=(n*sxy-sx*sy)/den;
  const base=(sy-k*sx)/n;
  return {k:r2(k),base:r2(base),n:n};
}
function calibSuggest(){
  const obp=Math.max(0,Math.min(100,+S.obp||0))*S.coef.obpK;
  const tyt=S.calib.filter(c=>c.type==="tyt");
  const out={};
  if(tyt.length===1){
    const c=tyt[0];
    out.tytK=r2((c.score-S.coef.tytBase-obp)/(c.net||1));
    out.tytBase=S.coef.tytBase;
    out.tytN=1;
  } else if(tyt.length>1){
    const f=fitLine(tyt.map(c=>({x:c.net,y:c.score-obp})));
    if(f&&f.k!==null){ out.tytK=f.k; out.tytBase=f.base; out.tytN=f.n; }
  }
  const alan=S.calib.filter(c=>c.type==="alan"&&c.ayt!=null);
  if(alan.length===1){
    const c=alan[0];
    out.ayAyt=r2((c.score-S.coef.ayBase-c.net*S.coef.ayTyt-obp)/(c.ayt||1));
    out.ayBase=S.coef.ayBase; out.alanN=1;
  } else if(alan.length>1){
    /* TYT katkÄ±sÄ± sabit kabul edilip AYT eÄŸimi ve taban Ã§Ã¶zÃ¼lÃ¼r */
    const f=fitLine(alan.map(c=>({x:c.ayt,y:c.score-obp-c.net*S.coef.ayTyt})));
    if(f&&f.k!==null){ out.ayAyt=f.k; out.ayBase=f.base; out.alanN=f.n; }
  }
  return out;
}
function applyCalib(){
  const s=calibSuggest();
  let n=0;
  ["tytBase","tytK","ayBase","ayAyt"].forEach(k=>{
    if(s[k]!==undefined&&isFinite(s[k])){ S.coef[k]=s[k]; n++; }
  });
  if(!n){ toast("Uygulanacak katsayÄ± yok"); return; }
  save(); renderScore(); renderCalib();
  toast(n+" katsayÄ± gerÃ§ek sonuca gÃ¶re ayarlandÄ± âœ“");
}
function calibError(){
  const obp=Math.max(0,Math.min(100,+S.obp||0))*S.coef.obpK;
  const rows=[];
  S.calib.forEach(c=>{
    let est=null;
    if(c.type==="tyt")est=r2(S.coef.tytBase+c.net*S.coef.tytK+obp);
    else if(c.ayt!=null)est=r2(S.coef.ayBase+c.net*S.coef.ayTyt+c.ayt*S.coef.ayAyt+obp);
    if(est!=null)rows.push({c:c,est:est,diff:r2(est-c.score)});
  });
  return rows;
}
function renderCalib(){
  const w=el("cbBox"); if(!w)return;
  if(!S.calib.length){
    w.innerHTML='<div class="empty">Elinde gerÃ§ek bir Ã–SYM sonucu varsa (geÃ§en yÄ±lki sÄ±navÄ±n gibi) netini ve puanÄ±nÄ± gir. Tahmin formÃ¼lÃ¼nÃ¼ kendi sonucuna gÃ¶re ayarlarÄ±m; bir sonuÃ§ bile ciddi fark yaratÄ±r.</div>';
    return;
  }
  const rows=calibError();
  let html=rows.map(r=>
    `<div class="dayrow"><span class="k">${r.c.type==="tyt"?"TYT":"Alan"} Â· ${r.c.net} net${r.c.ayt!=null?" + "+r.c.ayt:""}<br>
      <small>gerÃ§ek ${r.c.score} Â· tahmin ${r.est}</small></span>
     <span class="v" style="color:${Math.abs(r.diff)<5?"var(--success)":Math.abs(r.diff)<20?"var(--time)":"var(--danger)"}">
       ${r.diff>0?"+":""}${r.diff}
       <button class="del" onclick="delCalib(${r.c.id})">sil</button></span></div>`).join("");
  const s=calibSuggest();
  const parts=[];
  if(s.tytK!==undefined)parts.push("TYT: taban "+r2(s.tytBase)+" Â· Ã§arpan "+s.tytK+(s.tytN===1?" (tek sonuÃ§, yalnÄ±z Ã§arpan)":" ("+s.tytN+" sonuca gÃ¶re)"));
  if(s.ayAyt!==undefined)parts.push("Alan: taban "+r2(s.ayBase)+" Â· AYT Ã§arpanÄ± "+s.ayAyt+(s.alanN===1?" (tek sonuÃ§)":" ("+s.alanN+" sonuca gÃ¶re)"));
  if(parts.length){
    html+='<p class="hint" style="margin-top:14px;"><b>Ã–nerilen katsayÄ±lar</b><br>'+parts.map(esc).join("<br>")+'</p>';
    html+='<button class="btn green small" style="width:100%;margin-top:10px;" onclick="applyCalib()">KatsayÄ±larÄ± bunlara ayarla</button>';
  } else {
    html+='<p class="hint">Ä°kinci bir sonuÃ§ girersen taban puanÄ± da Ã§Ã¶zebilirim.</p>';
  }
  w.innerHTML=html;
}

/* ==================================================================
   3) MÃœFREDAT BÄ°TÄ°Å PROJEKSÄ°YONU
   ================================================================== */
function curriculumState(){
  let total=0,have=0;
  ALL_SUBJECTS.forEach(s=>s.topics.forEach(tp=>{
    total+=3; have+=tget(tkey(s.exam,s.name,tp)).st;
  }));
  return {total:total,have:have,left:total-have,pct:total?Math.round(have/total*100):0};
}
/* son N gÃ¼nde kaÃ§ kademe ilerlendi â€” tarih damgasÄ± yalnÄ±z 3. kademede
   tutulduÄŸu iÃ§in oradan sayÄ±lÄ±r, gerisi iÃ§in soru/Ã§alÄ±ÅŸma temposuna bakÄ±lÄ±r */
function curriculumRate(days){
  const t0=todayKey(),cut=addDaysKey(t0,-(days||45));
  let steps=0;
  Object.keys(S.topics).forEach(k=>{
    const t=S.topics[k];
    if(t.st===3&&t.ts&&t.ts>=cut)steps+=3;
  });
  /* konu bazlÄ± Ã§Ã¶zÃ¼len soru da ilerleme sayÄ±lÄ±r (kaba katkÄ±) */
  const q=topicSolvedAgg(days||45);
  const touched=Object.keys(q).length;
  steps+=Math.min(touched,40);
  return steps/(days||45);
}
function curriculumProjection(){
  const st=curriculumState();
  const rate=curriculumRate(45);
  const d=daysUntil(S.examDate);
  if(st.left<=0)return {done:true,pct:100};
  if(rate<=0.01)return {rate:0,left:st.left,pct:st.pct,days:null};
  const need=Math.ceil(st.left/rate);
  const date=addDaysKey(todayKey(),need);
  const fits=need<=d;
  const required=d>0?r2(st.left/d):null;
  return {rate:r2(rate),left:st.left,pct:st.pct,days:need,date:date,fits:fits,
          examDays:d,required:required};
}
function renderCurriculum(){
  const w=el("curBox"); if(!w)return;
  const p=curriculumProjection();
  if(p.done){ w.innerHTML='<div class="empty">BÃ¼tÃ¼n konular pekiÅŸtirilmiÅŸ ğŸ‰</div>'; return; }
  let html=`<div class="dayrow"><span class="k">MÃ¼fredat ilerlemesi</span><span class="v">%${p.pct}</span></div>
    <div class="bar" style="margin:10px 0 14px;"><i style="width:${p.pct}%"></i></div>`;
  if(!p.days){
    html+='<div class="empty">Son 45 gÃ¼nde Ã¶lÃ§Ã¼lebilir konu ilerlemesi yok. KonularÄ± iÅŸaretlemeye baÅŸlayÄ±nca buraya "bu hÄ±zla ne zaman biter" tahmini Ã§Ä±kar.</div>';
    w.innerHTML=html; return;
  }
  html+=`<div class="dayrow"><span class="k">Åu anki hÄ±z</span><span class="v">gÃ¼nde ${p.rate} kademe</span></div>
    <div class="dayrow"><span class="k">Bu hÄ±zla biter</span><span class="v" style="color:${p.fits?"var(--success)":"var(--danger)"}">
      ${parseKey(p.date).toLocaleDateString("tr-TR",{day:"numeric",month:"long",year:"numeric"})} Â· ${p.days} gÃ¼n</span></div>
    <div class="dayrow"><span class="k">SÄ±nava kalan</span><span class="v">${p.examDays} gÃ¼n</span></div>`;
  if(p.fits){
    html+='<p class="hint">Bu tempoyla mÃ¼fredatÄ± sÄ±navdan '+(p.examDays-p.days)+' gÃ¼n Ã¶nce bitirirsin. Kalan sÃ¼re tekrar ve denemeye kalÄ±r.</p>';
  } else {
    html+=`<div class="dayrow"><span class="k">Gereken hÄ±z</span><span class="v" style="color:var(--ochre-ink)">gÃ¼nde ${p.required} kademe</span></div>`;
    html+='<p class="hint">Bu hÄ±zla mÃ¼fredat sÄ±nava yetiÅŸmiyor. Ya tempoyu artÄ±rman ya da dÃ¼ÅŸÃ¼k aÄŸÄ±rlÄ±klÄ± konularÄ± gÃ¶zden Ã§Ä±karman gerekir â€” ikincisi Ã§oÄŸu zaman daha gerÃ§ekÃ§i.</p>';
  }
  w.innerHTML=html;
}

