    box.textContent="Ã‡alÄ±ÅŸÄ±yor âœ“ Â· "+items.length+" sonuÃ§ Â· "+ms+" ms Â· "+location.protocol+" Â· kaynak: "+src+
      " (kendi anahtarÄ±n)"+
      (c.raw?" Â· "+c.raw:"");
