function watchedMap(){ if(!S.watched||typeof S.watched!=="object")S.watched={}; return S.watched; }
function isWatched(v){ return !!(v&&v.id&&watchedMap()[v.id]); }
function watchedCount(){ return Object.keys(watchedMap()).length; }

function toggleWatched(i){
  const v=vidItems[i]; if(!v||!v.id)return false;
  const m=watchedMap();
  if(m[v.id]){
    delete m[v.id]; save(); renderVidList();
    toast("Ä°zledim iÅŸareti kaldÄ±rÄ±ldÄ±");
    return false;
  }
  const subj=(vidCtx&&vidCtx.subject)||"";
  const topic=(vidCtx&&vidCtx.topic)||"";
  const hoca=(vidCtx&&vidCtx.teacher)||"";
  m[v.id]={at:Date.now(),title:String(v.title||"").slice(0,120),subj:subj,topic:topic,
    ch:String(v.ch||"").slice(0,60),hoca:String(hoca).slice(0,60)};
  save();
  /* konu belliyse kademeyi ilerlet */
  let msg="Ä°zledim âœ“";
  if(subj&&topic){
    const key=topicKeyOf(subj,topic);
    if(key){
      const t=tget(key);
      if(t.st<1){
        tsetStatus(key,1);
        msg="Ä°zledim âœ“ Â· "+topic+" konusu \"iÅŸledim\" oldu";
      } else {
        msg="Ä°zledim âœ“ Â· "+topic;
      }
    }
  }
  renderVidList();
  if(el("topics")&&el("topics").classList.contains("active"))renderSubjects();
  toast(msg);
  return true;
}
function renderWatchedList(){
  const w=el("watchList"); if(!w)return;
  const m=watchedMap();
  const list=Object.keys(m).map(k=>Object.assign({id:k},m[k]))
    .sort((a,b)=>(b.at|0)-(a.at|0)).slice(0,40);
  const cnt=el("watchCount");
  if(cnt)cnt.textContent=Object.keys(m).length||"";
  if(!list.length){
    w.innerHTML='<div class="empty">HenÃ¼z izledim iÅŸareti koymadÄ±n. Video listesinde her kartÄ±n Ã¼stÃ¼ndeki âœ“ ile iÅŸaretleyebilirsin; konu belliyse o konu kendiliÄŸinden "iÅŸledim" olur.</div>';
    return;
  }
  w.innerHTML=list.map(x=>{
    const d=new Date(x.at||0);
    const when=isNaN(d)?"":d.toLocaleDateString("tr-TR",{day:"numeric",month:"long"});
    return '<div class="dayrow"><span class="k">'+esc(x.title||"video")+
      (x.subj?'<br><small>'+esc(x.subj)+(x.topic?" Â· "+esc(x.topic):"")+' Â· '+when+'</small>':"")+'</span>'+
      '<span class="v"><button class="del" onclick="unwatch(\''+x.id+'\')">kaldÄ±r</button></span></div>';
  }).join("");
}
function unwatch(id){
  const m=watchedMap();
  const bk=clone(m[id]);
  delete m[id]; save();
  if(bk)pushUndo("Ä°zledim iÅŸareti kaldÄ±rÄ±ldÄ±",()=>{ watchedMap()[id]=bk; });
  renderWatchedList();
  if(el("vidOverlay")&&el("vidOverlay").style.display==="flex")renderVidList();
}



/* ==================================================================
   BÄ°LDÄ°RÄ°MLER
   TarayÄ±cÄ± bildirimi; uygulama aÃ§Ä±kken ya da arka planda sekme
   olarak dururken Ã§alÄ±ÅŸÄ±r. Uygulama tamamen kapalÄ±yken bildirim
   gÃ¶ndermek bir sunucu gerektirir â€” o yÃ¼zden koÃ§ Ã¶zeti e-posta ile
   Apps Script Ã¼zerinden gÃ¶nderilir.
   ================================================================== */
function validTime(v){
  const m=/^(\d{2}):(\d{2})$/.exec(String(v||""));
  if(!m)return false;
  const h=+m[1],mi=+m[2];
  return h>=0&&h<=23&&mi>=0&&mi<=59;
}
function notifCfg(){
  if(!S.notif||typeof S.notif!=="object")S.notif={};
  const c=S.notif;
  c.on=!!c.on;
  c.pomo=c.pomo!==false;
  c.review=c.review!==false;
  c.evening=c.evening!==false;
  if(!validTime(c.eveningAt))c.eveningAt="21:00";
  if(typeof c.lastEvening!=="string")c.lastEvening="";
  if(typeof c.lastReview!=="string")c.lastReview="";
  return c;
}
function notifSupported(){
  try{ return typeof Notification!=="undefined"; }catch(e){ return false; }
}
function notifState(){
  if(!notifSupported())return "yok";
  try{ return Notification.permission; }catch(e){ return "yok"; }
}
function askNotif(){
  if(!notifSupported()){ toast("Bu tarayÄ±cÄ± bildirim desteklemiyor"); return Promise.resolve("yok"); }
  if(notifState()==="denied"){
    toast("Ä°zin daha Ã¶nce reddedilmiÅŸ â€” tarayÄ±cÄ± ayarlarÄ±ndan aÃ§man gerekiyor");
    notifDiag();
    return Promise.resolve("denied");
  }
  return Promise.resolve(Notification.requestPermission()).then(p=>{
    const c=notifCfg();
    c.on=(p==="granted");
    save(); renderNotifSettings(); notifDiag();
    if(p==="granted")notify("YKS Defterim","Bildirimler aÃ§Ä±ldÄ±. BÃ¶yle gÃ¶rÃ¼necek.","acildi");
    toast(p==="granted"?"Bildirimler aÃ§Ä±ldÄ± âœ“":"Bildirim izni verilmedi");
    return p;
  }).catch(()=>{ toast("Ä°zin istenemedi"); return "yok"; });
}
function notify(title,body,tag){
  const c=notifCfg();
  if(!c.on)return false;
  if(notifState()!=="granted")return false;
  const opts={body:body||"",tag:tag||"yks",icon:"icon-192.png",badge:"icon-192.png",lang:"tr"};
  /* DoÄŸrudan Notification dene. serviceWorker.ready bazÄ± durumlarda hiÃ§
     Ã§Ã¶zÃ¼lmÃ¼yor; ona baÄŸlanÄ±rsan bildirim sessizce hiÃ§ Ã§Ä±kmÄ±yor. */
  let ok1=false;
  try{ new Notification(title,opts); ok1=true; }catch(e){ ok1=false; }
  if(ok1)return true;
  /* BazÄ± tarayÄ±cÄ±lar (Ã¶zellikle mobil) yalnÄ±z service worker Ã¼zerinden
     bildirime izin veriyor; orada da zaman aÅŸÄ±mÄ± koy. */
  try{
    if(navigator.serviceWorker&&navigator.serviceWorker.ready){
      let bitti=false;
      const zaman=setTimeout(()=>{ bitti=true; },4000);
      navigator.serviceWorker.ready.then(reg=>{
        clearTimeout(zaman);
        if(bitti||!reg||!reg.showNotification)return;
        try{ reg.showNotification(title,opts); }catch(e){}
      }).catch(()=>{ clearTimeout(zaman); });
      return true;
    }
  }catch(e){}
  return false;
}
